  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0f172a;
      --panel: #111827;
      --panel-border: #243244;
      --text: #f8fafc;
      --muted: #94a3b8;
      --input: #172033;
      --accent: #38bdf8;
      --accent-dark: #0284c7;
      --error: #fb7185;
      --success: #34d399;
      --shadow: rgba(0, 0, 0, 0.35);
    }

