      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.65;
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      color: #dbeafe;
      font-size: 0.95rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      border: 1px solid #334155;
      border-radius: 14px;
