  </style>
</head>
<body>
  <main>
    <section class="support-card" aria-labelledby="support-title">
      <p class="eyebrow">Support</p>
      <h1 id="support-title">Contact our team</h1>
      <p class="intro">Tell us how to reach you and a support specialist will follow up shortly.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            placeholder="Alex Morgan"
            required
            aria-describedby="full-name-error"
          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            placeholder="alex@example.com"
            required
            aria-describedby="email-error"
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            placeholder="+1 555 123 4567"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use digits, spaces, hyphens, parentheses, or a leading +, such as +1 555 123 4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="success-message" id="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const successMessage = document.querySelector("#success-message");

    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Please enter your full name.";
          }

          if (value.trim().length < 2) {
            return "Full name must be at least 2 characters.";
          }

          return "";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          if (!value.trim()) {
            return "Please enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Please enter a valid email address.";
          }

          return "";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const phone = value.trim();
          if (!phone) {
            return "";
          }

          const phonePattern = /^\+?[0-9\s\-()]{7,20}$/;
          if (!phonePattern.test(phone)) {
            return "Use 7-20 characters with digits, spaces, hyphens, parentheses, or one leading +.";
          }

          return "";
        }
      }
    };

    function setError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        validateField(field);
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const validationResults = Object.values(fields).map(validateField);
      const isValid = validationResults.every(Boolean);
      successMessage.textContent = isValid ? "Thanks! Your support request is ready to send." : "";

      if (!isValid) {
        const firstInvalidField = Object.values(fields).find((field) => field.input.getAttribute("aria-invalid") === "true");
        firstInvalidField.input.focus();
      }
    });
  </script>
</body>
</html>
